package domain

// ---- Delegate ingestion (single entry and CSV import) ---------------------------

// ParticipantCreateRequest is the body of POST /api/v1/admin/participants/create.
// The membership ID and QR signature are generated by the server.
type ParticipantCreateRequest struct {
	FullName    string `json:"full_name"`
	Email       string `json:"email"`
	TeamName    string `json:"team_name"`
	DateOfBirth string `json:"date_of_birth"` // YYYY-MM-DD, optional
	VenueID     string `json:"venue_id"`      // optional
	// Values for existing custom fields, keyed by field_key, as typed.
	CustomAttributes map[string]string `json:"custom_attributes"`
}

// NewParticipant is one validated delegate ready to insert. Email is
// lower-cased; empty strings mean "not given" and are stored as NULL.
type NewParticipant struct {
	Line        int // CSV line number (1 = header); 0 for single entry
	FullName    string
	Email       string
	TeamName    string
	DateOfBirth string // YYYY-MM-DD
	VenueID     string
	// Custom field values, already converted to their field's type. Nil or
	// empty is stored as {}.
	CustomAttributes map[string]any
}

// CreatedParticipant is a delegate the ingestion just inserted.
type CreatedParticipant struct {
	Line         int    `json:"line,omitempty"`
	ID           string `json:"id"`
	MembershipID string `json:"membership_id"`
	FullName     string `json:"full_name"`
	Email        string `json:"email"`
	TeamName     string `json:"team_name"`
	DateOfBirth  string `json:"date_of_birth,omitempty"`
	VenueID      string `json:"venue_id,omitempty"`
	QRSignature  string `json:"qr_signature"`

	CustomAttributes map[string]any `json:"custom_attributes,omitempty"`
}

// ImportIssue is one CSV row that was not imported.
type ImportIssue struct {
	Line    int    `json:"line"`
	Email   string `json:"email,omitempty"`
	Message string `json:"message"`
}

// ImportOptions changes how an upload treats delegates already registered.
type ImportOptions struct {
	// UpdateExisting: a row whose email is already registered updates that
	// delegate instead of being skipped as a duplicate. Non-blank cells
	// overwrite; blank cells keep the stored value. Email and membership ID
	// never change, so passes already sent keep working.
	UpdateExisting bool
}

// UpdatedParticipant is a registered delegate an update-mode upload changed.
type UpdatedParticipant struct {
	Line         int      `json:"line"`
	ID           string   `json:"id"`
	MembershipID string   `json:"membership_id"`
	FullName     string   `json:"full_name"`
	Email        string   `json:"email"`
	Changed      []string `json:"changed"` // full_name, team_name, date_of_birth, venue_id or a field key
}

// ImportResult is the response of POST /api/v1/admin/participants/upload-csv.
// Every data row ends up in exactly one of Created, Updated, Unchanged,
// Duplicates or Errors.
type ImportResult struct {
	TotalRows  int                  `json:"total_rows"`
	Created    []CreatedParticipant `json:"created"`
	Updated    []UpdatedParticipant `json:"updated"`    // update mode only
	Unchanged  []ImportIssue        `json:"unchanged"`  // update mode: already registered, nothing new in the row
	Duplicates []ImportIssue        `json:"duplicates"` // email already registered (not update mode), or repeated in the file
	Errors     []ImportIssue        `json:"errors"`     // invalid rows, fix and upload again

	// Extra columns stored in custom_attributes, by field key. NewFields are
	// the ones registered by this upload (both display toggles off).
	CustomFields []string `json:"custom_fields"`
	NewFields    []string `json:"new_fields"`
	// Headers that were neither a core column nor stored (blank header, or a
	// reserved name such as venue_name from the seed script's format).
	IgnoredColumns []string `json:"ignored_columns"`
}

// Ingestion limits.
const (
	MaxParticipantNameLen  = 150 // participants.full_name
	MaxParticipantTeamLen  = 150 // participants.team_name
	MaxParticipantEmailLen = 255 // participants.email
	MaxImportRows          = 10000
	MaxImportBytes         = 5 << 20
)
